                  window.open(href, '_blank', 'noopener,noreferrer');
                }
              }
            };

            return (
              <a
                href={href}
                className="hover:underline underline-offset-2 cursor-pointer"
                style={{ color: "#ff2a6d", textDecorationColor: "rgba(255, 42, 109, 0.5)" }}
