                key={provider.id}
                provider={provider}
                configured={!!keyInfo}
                keyPreview={keyInfo?.keyPreview || null}
                onSave={onSave}
                onDelete={onDelete}
                isSaving={isSaving}
                isDeleting={deletingProvider === provider.id}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

