                </span>
              )}
            </div>
            {configured && keyPreview && (
              <span className="text-xs text-zinc-400 mt-0.5 block">
                Key: {keyPreview}...
              </span>
            )}
          </div>
        </div>

        <ChevronRight 
          className={`w-4 h-4 text-zinc-400 transition-transform ${isExpanded ? 'rotate-90' : ''}`} 
        />
      </button>

      {/* Expandable content */}
