/**
 * API Client - Base fetch wrapper with auth and error handling
 * 
 * All API calls should go through this client for consistency.
 */

const BASE_URL = 'http://localhost:3001';

export interface ApiError {
  message: string;
  status?: number;
}

export class ApiClientError extends Error {
  status?: number;

  constructor(message: string, status?: number) {
    super(message);
    this.name = 'ApiClientError';
    this.status = status;
  }
}

export interface RequestOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  body?: unknown;
  headers?: Record<string, string>;
}

/**
 * Make an authenticated API request
 */
export async function apiRequest<T>(
  endpoint: string,
  options: RequestOptions = {}
): Promise<T> {
  const { method = 'GET', body, headers: customHeaders } = options;

  const headers: Record<string, string> = {
    ...customHeaders,
  };

  if (body) {
    headers['Content-Type'] = 'application/json';
  }

  const response = await fetch(`${BASE_URL}${endpoint}`, {
    method,
    credentials: 'include', // Include httpOnly cookies
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  // Handle session expiry
  if (response.status === 401) {
    throw new ApiClientError('Session expired', 401);
  }

  if (!response.ok) {
    let message = `HTTP ${response.status}`;
    try {
      const errorData = await response.json();
      message = errorData.message || errorData.error || message;
    } catch {
      // Ignore JSON parse errors
    }
    throw new ApiClientError(message, response.status);
  }

  // Handle empty responses
  const contentType = response.headers.get('content-type');
  if (!contentType || !contentType.includes('application/json')) {
    return {} as T;
  }

  return response.json();
}

/**
 * Auth API client with raw fetch access
 * Use this when you need more control over the response
 */
export const authAPI = {
  /**
   * Make an authenticated fetch request
   * Returns the raw Response object for custom handling
   */
  fetch: async (endpoint: string, options: RequestInit = {}): Promise<Response> => {
    return fetch(`${BASE_URL}${endpoint}`, {
      ...options,
      credentials: 'include',
    });
  },
};

import { Router, Request, Response } from 'express';
import { requireAuth } from '../auth/index.js';
import { saveApiKey, listApiKeys, deleteApiKey } from '../auth/api-keys.js';

const router = Router();

router.use(requireAuth);

// Request body types
interface SaveApiKeyBody {
  apiKey: string;
}

// Valid API key providers
const VALID_PROVIDERS = [
  'anthropic', 'openai', 'kimi', 'opencode', 'google', 'mistral',
  'groq', 'openrouter', 'xai',
  'bedrock', 'azure'
] as const;
type ValidProvider = typeof VALID_PROVIDERS[number];

// ============================================
// LIST API KEYS
// ============================================
router.get('/', async (req: Request, res: Response) => {
  try {
    const keys = await listApiKeys(req.userId!);
    res.json({ keys });
  } catch (err) {
    console.error('[API-KEYS] List error:', err);
    res.status(500).json({ error: 'Failed to list API keys' });
  }
});

// ============================================
// SAVE API KEY
// ============================================
router.post('/:provider', async (req: Request, res: Response) => {
  try {
    const provider = req.params.provider as string;
    const { apiKey } = req.body as SaveApiKeyBody;

    if (!apiKey) {
      return res.status(400).json({ error: 'API key required' });
    }

    // Validate provider
    if (!VALID_PROVIDERS.includes(provider as ValidProvider)) {
      return res.status(400).json({ error: `Invalid provider. Valid: ${VALID_PROVIDERS.join(', ')}` });
    }

    const key = await saveApiKey(req.userId!, provider, apiKey);
    res.json(key);
  } catch (err) {
    console.error('[API-KEYS] Save error:', err);
    res.status(500).json({ error: 'Failed to save API key' });
  }
});

// ============================================
// DELETE API KEY
// ============================================
router.delete('/:provider', async (req: Request, res: Response) => {
  try {
    const provider = req.params.provider as string;
    await deleteApiKey(req.userId!, provider);
    res.json({ success: true });
  } catch (err) {
    console.error('[API-KEYS] Delete error:', err);
    res.status(500).json({ error: 'Failed to delete API key' });
  }
});

export default router;

