                  ? 'bg-zinc-900 text-white' 
                  : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
              }`}
            >
              AWS Profile
            </button>
            <button
              onClick={() => setAuthMode('credentials')}
              className={`px-3 py-1.5 text-xs font-medium rounded-lg transition-colors ${
                authMode === 'credentials' 
                  ? 'bg-zinc-900 text-white' 
                  : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
              }`}
            >
              Access Keys
