/**
 * Model Configuration with User API Keys
 * 
 * Provides functions to configure Pi AI models with user-provided
 * API keys stored in the database (BYOK model).
 * 
 * Note: Pi AI reads API keys from environment variables, so we set
 * them at runtime before calling getModel().
 */

import { getModel, type Model } from '@mariozechner/pi-ai';
import { getApiKey } from '../auth/api-keys.js';

/**
 * Map normie provider names to Pi provider names
 */
export const PROVIDER_ALIAS: Record<string, string> = {
  bedrock: "amazon-bedrock",
  azure: "azure-openai-responses",
};

/**
 * Map of provider IDs to their environment variable names
 */
export const PROVIDER_ENV_KEYS: Record<string, string[]> = {
  anthropic: ["ANTHROPIC_API_KEY"],
  openai: ["OPENAI_API_KEY"],
  google: ["GEMINI_API_KEY", "GOOGLE_API_KEY"],
  groq: ["GROQ_API_KEY"],
  xai: ["XAI_API_KEY"],
  mistral: ["MISTRAL_API_KEY"],
  openrouter: ["OPENROUTER_API_KEY"],
  ollama: [], // Local, no API key needed
  "amazon-bedrock": ["AWS_ACCESS_KEY_ID", "AWS_SECRET_ACCESS_KEY"],
  "azure-openai-responses": ["AZURE_OPENAI_API_KEY"],
};

export interface ConfiguredModelResult {
  model: Model<any> | null;
  error?: string;
  keySource?: 'user' | 'env' | 'none';
}

/**
 * Set the API key for a provider at runtime by setting the environment variable.
 * This works because pi-ai reads from process.env at model fetch time.
 */
function setProviderApiKey(provider: string, apiKey: string): void {
  const envKeys = PROVIDER_ENV_KEYS[provider];
  if (envKeys && envKeys.length > 0) {
    // Set the primary environment variable
    process.env[envKeys[0]] = apiKey;
  }
}

/**
 * Configure a provider with the user's API key.
 * Falls back to environment variable if no user key.
 */
export async function configureProviderWithUserKey(
  userId: string,
  provider: string
): Promise<{ configured: boolean; keySource: 'user' | 'env' | 'none' }> {
  const mappedProvider = PROVIDER_ALIAS[provider] || provider;

  // 1. Try to get user's API key from database
  const userKey = await getApiKey(userId, provider);

  if (userKey) {
    // Set environment variable at runtime
    setProviderApiKey(mappedProvider, userKey);
    console.log(`[ModelConfig] Using user's API key for ${provider}`);
    return { configured: true, keySource: 'user' };
  }

  // 2. Check for environment variable
  const envKeys = PROVIDER_ENV_KEYS[mappedProvider] || [];
  const hasEnvKey = envKeys.some(k => process.env[k]);

  if (hasEnvKey) {
    console.log(`[ModelConfig] Using environment key for ${provider}`);
    return { configured: true, keySource: 'env' };
  }

  // 3. No key available
  console.warn(`[ModelConfig] No API key configured for ${provider}`);
  return { configured: false, keySource: 'none' };
}

/**
 * Configure AWS Bedrock with user credentials.
 */
export async function configureBedrockProvider(
  userId: string
): Promise<{ configured: boolean; error?: string }> {
  const userKey = await getApiKey(userId, 'bedrock');

  if (userKey) {
    try {
      const credentials = JSON.parse(userKey);

      if (credentials.authMode === 'profile') {
        // For profile-based auth, we need AWS SDK to pick up the profile
        // This requires AWS_PROFILE env var
        process.env.AWS_PROFILE = credentials.profile || 'default';
      } else {
        // Set AWS credentials as environment variables
        process.env.AWS_ACCESS_KEY_ID = credentials.accessKey;
        process.env.AWS_SECRET_ACCESS_KEY = credentials.secretKey;
        if (credentials.region) {
          process.env.AWS_REGION = credentials.region;
        }
      }

      console.log('[ModelConfig] Configured Bedrock with user credentials');
      return { configured: true };
    } catch (err) {
      console.error('[ModelConfig] Failed to parse Bedrock credentials:', err);
      return { configured: false, error: 'Invalid Bedrock credentials format' };
    }
  }

  // Check for environment credentials
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('[ModelConfig] Using environment credentials for Bedrock');
    return { configured: true };
  }

  return { configured: false, error: 'No Bedrock credentials configured' };
}

/**
 * Configure Azure OpenAI with user credentials.
 */
export async function configureAzureProvider(
  userId: string
): Promise<{ configured: boolean; error?: string }> {
  const userKey = await getApiKey(userId, 'azure');

  if (userKey) {
    try {
      const credentials = JSON.parse(userKey);

      // Set Azure environment variables
      process.env.AZURE_OPENAI_API_KEY = credentials.apiKey;
      process.env.AZURE_OPENAI_RESOURCE_NAME = credentials.resourceName;
      process.env.AZURE_OPENAI_DEPLOYMENT_NAME = credentials.deploymentName;
      if (credentials.apiVersion) {
        process.env.AZURE_OPENAI_API_VERSION = credentials.apiVersion;
      }

      console.log('[ModelConfig] Configured Azure OpenAI with user credentials');
      return { configured: true };
    } catch (err) {
      console.error('[ModelConfig] Failed to parse Azure credentials:', err);
      return { configured: false, error: 'Invalid Azure credentials format' };
    }
  }

  // Check for environment credentials
  if (process.env.AZURE_OPENAI_API_KEY) {
    console.log('[ModelConfig] Using environment credentials for Azure');
    return { configured: true };
  }

  return { configured: false, error: 'No Azure credentials configured' };
}

/**
 * Get a configured model for a provider, using user's API key.
 * 
 * This is the main entry point for getting models with user credentials.
 */
export async function getConfiguredModel(
  userId: string,
  provider: string,
  modelId: string
): Promise<ConfiguredModelResult> {
  const mappedProvider = PROVIDER_ALIAS[provider] || provider;

  // Handle complex providers differently
  if (mappedProvider === 'amazon-bedrock') {
    const result = await configureBedrockProvider(userId);
    if (!result.configured) {
      return { model: null, error: result.error };
    }
  } else if (mappedProvider === 'azure-openai-responses') {
    const result = await configureAzureProvider(userId);
    if (!result.configured) {
      return { model: null, error: result.error };
    }
  } else {
    // Simple API key providers
    const result = await configureProviderWithUserKey(userId, provider);
    if (!result.configured) {
      return { 
        model: null, 
        error: `No API key configured for ${provider}. Add your key in Settings > Providers.`,
        keySource: result.keySource,
      };
    }
  }

  // Get the model
  try {
    const model = getModel(mappedProvider as any, modelId as any);
    return { model };
  } catch (err) {
    return { model: null, error: `Model not found: ${provider}/${modelId}` };
  }
}

/**
 * Check if a provider has an API key configured (user or env)
 */
export async function hasProviderKey(userId: string, provider: string): Promise<boolean> {
  // Check user key first
  const userKey = await getApiKey(userId, provider);
  if (userKey) return true;

  // Check environment
  const mappedProvider = PROVIDER_ALIAS[provider] || provider;
  const envKeys = PROVIDER_ENV_KEYS[mappedProvider] || [];
  return envKeys.some(k => process.env[k]);
}

/**
 * Pi Agent Configuration Module
 * 
